window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-928c36a09d184e28"]={"versions": [{"id": "FIG-928c36a09d184e28", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Konfigurationsdiagramm im Kontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm veranschaulicht beispielhaft die Zerlegung und Zuordnung von Ausführungsschritten (<code>SoftwarePackageStep</code>) innerhalb eines übergeordneten <code>UcmStep</code> sowie deren referenzierende Verknüpfung zu den zugehörigen Software-Paketen (<code>SoftwarePackage</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>UcmStep</code>: Übergeordnetes Aggregat bzw. Container für die Teilschritte der Software-Aktualisierung.\n</li><li><code>SoftwarePackageStep_1</code>, <code>SoftwarePackageStep_2</code>, <code>SoftwarePackageStep_3</code>, <code>SoftwarePackageStep_4</code>: Konkrete Sequenzschritte, die über Kompositionsrelationen mit fester Reihenfolge/Index (1 bis 4) an <code>UcmStep</code> angebunden sind.\n</li><li><code>SoftwarePackage_A</code>, <code>SoftwarePackage_B</code>, <code>SoftwarePackage_C</code>: Ziel-Softwarepakete, auf die über gerichtete Pfeile mit Aktionsrollen (<code>transfer</code>, <code>process</code>) referenziert wird.\n</li><li>Beistellender Textblock „Steps for Software Activation“: Listet die textuelle Semantik der Schritte 1 bis 3 (Schritt 4 am unteren Bildrand angeschnitten) auf.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert einen sequentiellen Ablauf zur Software-Aktivierung:</p>\n<ol class=\"fig-list\"><li><code>SoftwarePackageStep_1</code> (Index 1): Führt die Aktion <code>transfer</code> parallel bzw. gebündelt für alle drei Zielpakete aus (<code>SoftwarePackage_A</code>, <code>SoftwarePackage_B</code>, <code>SoftwarePackage_C</code>).\n</li><li><code>SoftwarePackageStep_2</code> (Index 2): Führt die Aktion <code>process</code> gezielt auf <code>SoftwarePackage_A</code> aus.\n</li><li><code>SoftwarePackageStep_3</code> (Index 3): Führt die Aktion <code>process</code> gezielt auf <code>SoftwarePackage_B</code> aus.\n</li><li><code>SoftwarePackageStep_4</code> (Index 4): Führt die Aktion <code>process</code> gezielt auf <code>SoftwarePackage_C</code> aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als exemplarisches Konfigurationsmuster für Manifest-Modellierer im UCM-Umfeld. Es definiert die Trennung zwischen Transfer- und Verarbeitungsschritten: Mehrere Pakete können in einem gemeinsamen Initialschritt transferiert werden (<code>transfer</code>), während die nachfolgende Verarbeitung (<code>process</code>) paketweise in diskreten, geordneten Einzelschritten (<code>SoftwarePackageStep</code>) erfolgen kann.</p>"}, {"id": "FIG-ce5ee214767e241d", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Konfigurationsdiagramm im Kontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm veranschaulicht beispielhaft die Zerlegung und Zuordnung von Ausführungsschritten (<code>SoftwarePackageStep</code>) innerhalb eines übergeordneten <code>UcmStep</code> sowie deren referenzierende Verknüpfung zu den zugehörigen Software-Paketen (<code>SoftwarePackage</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>UcmStep</code>: Übergeordnetes Aggregat bzw. Container für die Teilschritte der Software-Aktualisierung.\n</li><li><code>SoftwarePackageStep_1</code>, <code>SoftwarePackageStep_2</code>, <code>SoftwarePackageStep_3</code>, <code>SoftwarePackageStep_4</code>: Konkrete Sequenzschritte, die über Kompositionsrelationen mit fester Reihenfolge/Index (1 bis 4) an <code>UcmStep</code> angebunden sind.\n</li><li><code>SoftwarePackage_A</code>, <code>SoftwarePackage_B</code>, <code>SoftwarePackage_C</code>: Ziel-Softwarepakete, auf die über gerichtete Pfeile mit Aktionsrollen (<code>transfer</code>, <code>process</code>) referenziert wird.\n</li><li>Beistellender Textblock „Steps for Software Activation“: Listet die textuelle Semantik der Einzelschritte 1 bis 4 vollständig auf (<code>1. Transfer all three SoftwarePackages</code>, <code>2. Process SoftwarePackage_A</code>, <code>3. Process SoftwarePackage_B</code>, <code>4. Process SoftwarePackage_C</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert einen sequentiellen Ablauf zur Software-Aktivierung:</p>\n<ol class=\"fig-list\"><li><code>SoftwarePackageStep_1</code> (Index 1): Führt die Aktion <code>transfer</code> parallel bzw. gebündelt für alle drei Zielpakete aus (<code>SoftwarePackage_A</code>, <code>SoftwarePackage_B</code>, <code>SoftwarePackage_C</code>).\n</li><li><code>SoftwarePackageStep_2</code> (Index 2): Führt die Aktion <code>process</code> gezielt auf <code>SoftwarePackage_A</code> aus.\n</li><li><code>SoftwarePackageStep_3</code> (Index 3): Führt die Aktion <code>process</code> gezielt auf <code>SoftwarePackage_B</code> aus.\n</li><li><code>SoftwarePackageStep_4</code> (Index 4): Führt die Aktion <code>process</code> gezielt auf <code>SoftwarePackage_C</code> aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient als exemplarisches Konfigurationsmuster für Manifest-Modellierer im UCM-Umfeld. Es definiert die Trennung zwischen Transfer- und Verarbeitungsschritten: Mehrere Pakete können in einem gemeinsamen Initialschritt transferiert werden (<code>transfer</code>), während die nachfolgende Verarbeitung (<code>process</code>) paketweise in diskreten, geordneten Einzelschritten (<code>SoftwarePackageStep</code>) erfolgen kann.</p>"}], "trans": [{"from": "FIG-928c36a09d184e28", "to": "FIG-ce5ee214767e241d", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Textliste „Steps for Software Activation“: Der vierte Listeneintrag „4. Process SoftwarePackage_C“ ist nun vollständig im sichtbaren Bildbereich dargestellt (in der Vorgängerfassung am unteren Bildrand abgeschnitten).\n</li></ul>"}]};
